//! Declares the app's commands to Tauri, which writes each one's `allow-` and `deny-` permission
//! (`permissions/autogenerated`) for `capabilities/default.json` to grant.

/// The thirteen commands the app answers (plan, Global Constraints). `commands::NAMES` and the capability file agree
/// with this list, which a test checks.
const COMMANDS: &[&str] = &[
    "installation",
    "cli",
    "open_in_terminal",
    "copy_text",
    "open_link",
    "open_profile",
    "get_settings",
    "set_folders",
    "set_login_item",
    "updater_state",
    "check_for_updates",
    "install_update",
    "take_deep_link",
];

fn main() {
    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(tauri_build::AppManifest::new().commands(COMMANDS)),
    )
    .expect("the app's command manifest is valid");
}
